import React, { useState, useEffect } from 'react';
import {
    getAllStocks,
    getAllSales,
    getAllReturns,
    createStock,
    createSale,
    createReturn,
    updateStock
} from '../../services/store1Service';

const Store1Operations = () => {
    // State for active tab
    const [activeTab, setActiveTab] = useState('stock');
    
    // States for data
    const [stocks, setStocks] = useState([]);
    const [sales, setSales] = useState([]);
    const [returns, setReturns] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [showAddModal, setShowAddModal] = useState(false);

    // Form states
    const [stockForm, setStockForm] = useState({
        productCode: '',
        category: '',
        productName: '',
        size: '',
        color: '',
        quantity: 0,
        unitPrice: 0,
        createdDate: new Date().toISOString()
    });

    const [saleForm, setSaleForm] = useState({
        productId: '',
        quantity: 0,
        customerName: '',
        customerPhone: '',
        paymentMethod: 'Credit Card'
    });

    const [returnForm, setReturnForm] = useState({
        saleId: '',
        quantity: 0,
        returnReason: ''
    });

    useEffect(() => {
        fetchData();
    }, [activeTab]);

    const fetchData = async () => {
        setLoading(true);
        setError(null);
        try {
            switch (activeTab) {
                case 'stock':
                    const stockResponse = await getAllStocks();
                    if (stockResponse.success) {
                        setStocks(stockResponse.store1Stocks);
                    }
                    break;
                case 'sale':
                    const saleResponse = await getAllSales();
                    if (saleResponse.success) {
                        setSales(saleResponse.store1Sales);
                    }
                    break;
                case 'return':
                    const returnResponse = await getAllReturns();
                    if (returnResponse.success) {
                        setReturns(returnResponse.store1Returns);
                    }
                    break;
            }
        } catch (err) {
            setError('Veri yüklenirken bir hata oluştu');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError(null);
        try {
            let response;
            switch (activeTab) {
                case 'stock':
                    response = await createStock(stockForm);
                    if (response.success) {
                        setStockForm({
                            productCode: '',
                            category: '',
                            productName: '',
                            size: '',
                            color: '',
                            quantity: 0,
                            unitPrice: 0,
                            createdDate: new Date().toISOString()
                        });
                    }
                    break;
                case 'sale':
                    response = await createSale(saleForm);
                    if (response.success) {
                        setSaleForm({
                            productId: '',
                            quantity: 0,
                            customerName: '',
                            customerPhone: '',
                            paymentMethod: 'Credit Card'
                        });
                    }
                    break;
                case 'return':
                    response = await createReturn(returnForm);
                    if (response.success) {
                        setReturnForm({
                            saleId: '',
                            quantity: 0,
                            returnReason: ''
                        });
                    }
                    break;
            }
            if (response.success) {
                setShowAddModal(false);
                fetchData();
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('İşlem sırasında bir hata oluştu');
        } finally {
            setLoading(false);
        }
    };

    const getFilteredData = () => {
        switch (activeTab) {
            case 'stock':
                return stocks.filter(stock =>
                    Object.values(stock).some(value =>
                        value.toString().toLowerCase().includes(searchTerm.toLowerCase())
                    )
                );
            case 'sale':
                return sales.filter(sale =>
                    Object.values(sale).some(value =>
                        value.toString().toLowerCase().includes(searchTerm.toLowerCase())
                    )
                );
            case 'return':
                return returns.filter(ret =>
                    Object.values(ret).some(value =>
                        value.toString().toLowerCase().includes(searchTerm.toLowerCase())
                    )
                );
            default:
                return [];
        }
    };

    const renderForm = () => {
        switch (activeTab) {
            case 'stock':
                return (
                    <div className="grid grid-cols-2 gap-4">
                        <input
                            type="text"
                            placeholder="Ürün Kodu"
                            className="border p-2 rounded"
                            value={stockForm.productCode}
                            onChange={(e) => setStockForm({...stockForm, productCode: e.target.value})}
                        />
                        <input
                            type="text"
                            placeholder="Kategori"
                            className="border p-2 rounded"
                            value={stockForm.category}
                            onChange={(e) => setStockForm({...stockForm, category: e.target.value})}
                        />
                        <input
                            type="text"
                            placeholder="Ürün Adı"
                            className="border p-2 rounded"
                            value={stockForm.productName}
                            onChange={(e) => setStockForm({...stockForm, productName: e.target.value})}
                        />
                        <input
                            type="text"
                            placeholder="Beden"
                            className="border p-2 rounded"
                            value={stockForm.size}
                            onChange={(e) => setStockForm({...stockForm, size: e.target.value})}
                        />
                        <input
                            type="text"
                            placeholder="Renk"
                            className="border p-2 rounded"
                            value={stockForm.color}
                            onChange={(e) => setStockForm({...stockForm, color: e.target.value})}
                        />
                        <input
                            type="number"
                            placeholder="Miktar"
                            className="border p-2 rounded"
                            value={stockForm.quantity}
                            onChange={(e) => setStockForm({...stockForm, quantity: parseInt(e.target.value)})}
                        />
                        <input
                            type="number"
                            placeholder="Birim Fiyat"
                            className="border p-2 rounded"
                            value={stockForm.unitPrice}
                            onChange={(e) => setStockForm({...stockForm, unitPrice: parseFloat(e.target.value)})}
                        />
                    </div>
                );
            case 'sale':
                return (
                    <div className="grid grid-cols-2 gap-4">
                        <input
                            type="text"
                            placeholder="Ürün ID"
                            className="border p-2 rounded"
                            value={saleForm.productId}
                            onChange={(e) => setSaleForm({...saleForm, productId: e.target.value})}
                        />
                        <input
                            type="number"
                            placeholder="Miktar"
                            className="border p-2 rounded"
                            value={saleForm.quantity}
                            onChange={(e) => setSaleForm({...saleForm, quantity: parseInt(e.target.value)})}
                        />
                        <input
                            type="text"
                            placeholder="Müşteri Adı"
                            className="border p-2 rounded"
                            value={saleForm.customerName}
                            onChange={(e) => setSaleForm({...saleForm, customerName: e.target.value})}
                        />
                        <input
                            type="text"
                            placeholder="Müşteri Telefonu"
                            className="border p-2 rounded"
                            value={saleForm.customerPhone}
                            onChange={(e) => setSaleForm({...saleForm, customerPhone: e.target.value})}
                        />
                        <select
                            className="border p-2 rounded col-span-2"
                            value={saleForm.paymentMethod}
                            onChange={(e) => setSaleForm({...saleForm, paymentMethod: e.target.value})}
                        >
                            <option value="Credit Card">Kredi Kartı</option>
                            <option value="Cash">Nakit</option>
                            <option value="Bank Transfer">Banka Transferi</option>
                        </select>
                    </div>
                );
            case 'return':
                return (
                    <div className="grid grid-cols-2 gap-4">
                        <input
                            type="text"
                            placeholder="Satış ID"
                            className="border p-2 rounded"
                            value={returnForm.saleId}
                            onChange={(e) => setReturnForm({...returnForm, saleId: e.target.value})}
                        />
                        <input
                            type="number"
                            placeholder="Miktar"
                            className="border p-2 rounded"
                            value={returnForm.quantity}
                            onChange={(e) => setReturnForm({...returnForm, quantity: parseInt(e.target.value)})}
                        />
                        <textarea
                            placeholder="İade Nedeni"
                            className="border p-2 rounded col-span-2"
                            value={returnForm.returnReason}
                            onChange={(e) => setReturnForm({...returnForm, returnReason: e.target.value})}
                            rows="3"
                        />
                    </div>
                );
        }
    };

    const renderTable = () => {
        const data = getFilteredData();
        
        if (loading) {
            return <div className="text-center py-4">Yükleniyor...</div>;
        }

        if (error) {
            return <div className="text-center text-red-500 py-4">{error}</div>;
        }

        if (data.length === 0) {
            return <div className="text-center py-4">Veri bulunamadı</div>;
        }

        switch (activeTab) {
            case 'stock':
                return (
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Ürün Kodu</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Kategori</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Ürün Adı</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Beden</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Renk</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Miktar</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Birim Fiyat</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {data.map((stock) => (
                                <tr key={stock.id}>
                                    <td className="px-6 py-4 whitespace-nowrap">{stock.productCode}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{stock.category}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{stock.productName}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{stock.size}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{stock.color}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{stock.quantity}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(stock.unitPrice)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                );
            case 'sale':
                return (
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Müşteri Adı</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Telefon</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Miktar</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Toplam Fiyat</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Ödeme Yöntemi</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {data.map((sale) => (
                                <tr key={sale.id}>
                                    <td className="px-6 py-4 whitespace-nowrap">{sale.customerName}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{sale.customerPhone}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{sale.quantity}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(sale.totalPrice)}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap">{sale.paymentMethod}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                );
            case 'return':
                return (
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Miktar</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">İade Nedeni</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {data.map((ret) => (
                                <tr key={ret.id}>
                                    <td className="px-6 py-4 whitespace-nowrap">{ret.quantity}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{ret.returnReason}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                );
        }
    };

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <div className="flex space-x-4">
                    <button
                        onClick={() => setShowAddModal(true)}
                        className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
                    >
                        Yeni Ekle
                    </button>
                    <input
                        type="text"
                        placeholder="Ara..."
                        className="border p-2 rounded w-64"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
                <div className="flex space-x-2">
                    <button
                        onClick={() => setActiveTab('stock')}
                        className={`px-4 py-2 rounded ${activeTab === 'stock' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
                    >
                        Stok
                    </button>
                    <button
                        onClick={() => setActiveTab('sale')}
                        className={`px-4 py-2 rounded ${activeTab === 'sale' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
                    >
                        Satış
                    </button>
                    <button
                        onClick={() => setActiveTab('return')}
                        className={`px-4 py-2 rounded ${activeTab === 'return' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
                    >
                        İade
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-lg shadow overflow-hidden">
                <div className="overflow-x-auto">
                    {renderTable()}
                </div>
            </div>

            {showAddModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center">
                    <div className="bg-white p-6 rounded-lg w-full max-w-2xl">
                        <h2 className="text-xl font-bold mb-4">
                            {activeTab === 'stock' ? 'Yeni Stok Ekle' :
                             activeTab === 'sale' ? 'Yeni Satış Ekle' :
                             'Yeni İade Ekle'}
                        </h2>
                        <form onSubmit={handleSubmit}>
                            {renderForm()}
                            <div className="flex justify-end space-x-2 mt-4">
                                <button
                                    type="button"
                                    onClick={() => setShowAddModal(false)}
                                    className="px-4 py-2 border rounded"
                                >
                                    İptal
                                </button>
                                <button
                                    type="submit"
                                    className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
                                    disabled={loading}
                                >
                                    {loading ? 'Kaydediliyor...' : 'Kaydet'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Store1Operations;
